insert into public.exercises (slug, visibility, category, level, title, content) values
  ('fd01', 'library', 'doigts', 'all', '{"fr":"Suspension passive (Dead hang)","en":"Passive Hang (Dead Hang)","es":"Suspensión pasiva (Dead hang)"}'::jsonb, '{"fr":{"description":"Force maximale des fléchisseurs, adaptation tendineuse","subcategory":"Suspension / gainage doigts","muscles":"Fléchisseurs des doigts, Avant-bras","cues":"Épaules engagées et légèrement en dépression (pas de «shrug»), omoplates serrées, coudes légèrement fléchis.","dose":"4–6 x 10s suspension / 2 min repos","contraindications":"Échauffement des doigts obligatoire (10–15 min). Progressivité du lest indispensable ; prudence chez les jeunes en croissance.","equipment":["poutre"],"disciplines":["Bloc","Voie","Polyvalent"],"energy":["Force maximale"],"variants":[{"name":"Suspension 2 mains, prise jug/bac","desc":"2–3 x 8–10s, grande prise, poids de corps, pieds proches du sol."},{"name":"Suspension bi-doigts / demi-crimp sur réglette 20mm","desc":"Poids de corps, prise à 4 doigts, position demi-crimp, 4–6 x 10s."},{"name":"Suspension mono-doigt lestée","desc":"Réglette 12–15mm, annulaire + majeur, lest 5–15% du poids de corps."}]},"en":{"description":"Maximal flexor strength, tendon adaptation","subcategory":"Hang / finger conditioning","muscles":"Finger flexors, Forearms","cues":"Engage the shoulders in slight depression (no shrugging), squeeze the shoulder blades, keep elbows slightly bent.","dose":"4–6 x 10s hang / 2 min rest","contraindications":"Thorough finger warm-up required (10–15 min). Progressive loading is essential; use caution with young climbers still growing.","equipment":["hangboard"],"disciplines":["Boulder","Route","All-round"],"energy":["Maximal strength"],"variants":[{"name":"Two-hand hang, jug/large hold","desc":"2–3 x 8–10s, large hold, bodyweight, feet close to the ground."},{"name":"Two-finger / half-crimp hang on a 20mm edge","desc":"Bodyweight, 4-finger half-crimp position, 4–6 x 10s."},{"name":"Weighted one-finger hang","desc":"12–15mm edge, ring + middle finger, added load 5–15% of bodyweight."}]},"es":{"description":"Fuerza máxima de los flexores, adaptación tendinosa","subcategory":"Suspensión / acondicionamiento de dedos","muscles":"Flexores de los dedos, Antebrazos","cues":"Hombros activos y ligeramente en depresión (sin encogerlos), escápulas apretadas, codos ligeramente flexionados.","dose":"4–6 x 10s de suspensión / 2 min de descanso","contraindications":"Calentamiento de dedos obligatorio (10–15 min). Es indispensable una progresividad del lastre; precaución con los jóvenes en crecimiento.","equipment":["tabla de dedos (hangboard)"],"disciplines":["Bloque","Vía","Polivalente"],"energy":["Fuerza máxima"],"variants":[{"name":"Suspensión a dos manos, presa de canto grande","desc":"2–3 x 8–10s, presa grande, peso corporal, pies cerca del suelo."},{"name":"Suspensión a dos dedos / medio-crimp en regleta de 20mm","desc":"Peso corporal, presa a 4 dedos, posición medio-crimp, 4–6 x 10s."},{"name":"Suspensión a un dedo lastrada","desc":"Regleta de 12–15mm, anular + corazón, lastre del 5–15% del peso corporal."}]},"meta":{"minLevel":0,"difficulty":2,"mastery":"faible","duration":12,"period":"generale","publics":["mixte"],"ageGroups":["moins18","jeuneAdulte","plus30","plus50"],"equipment":["poutre"],"disciplines":["bloc","voie","polyvalent"],"energy":["force-max"],"pose":{"pose":"hang_two_hand","equip":"bar","variants":null,"weight":[false,false,false]}}}'::jsonb),
  ('fd02', 'library', 'doigts', 'inter', '{"fr":"Repeaters (méthode 7/3)","en":"Repeaters (7/3 Method)","es":"Repeaters (método 7/3)"}'::jsonb, '{"fr":{"description":"Résistance à la force / puissance aérobie locale des doigts","subcategory":"Résistance-force doigts","muscles":"Fléchisseurs des doigts, Avant-bras","cues":"Garder les épaules actives tout au long de la série, ne pas laisser retomber le buste entre les répétitions.","dose":"6 x (7s suspension / 3s repos), 3 min entre séries","contraindications":"Ne pas aller jusqu''à l''échec les premières séances. Surveiller toute douleur de poulie (A2).","equipment":["poutre"],"disciplines":["Bloc","Voie"],"energy":["Résistance (anaérobie lactique)"],"variants":[{"name":"Réglette large (30mm+)","desc":"4 répétitions du cycle 7/3, prise confortable."},{"name":"Réglette 20mm","desc":"6 répétitions complètes, poids de corps."},{"name":"Réglette 15mm mono-doigt ou lestée","desc":"6–8 répétitions, charge additionnelle légère."}]},"en":{"description":"Strength-endurance / local aerobic power of the fingers","subcategory":"Finger strength-endurance","muscles":"Finger flexors, Forearms","cues":"Keep the shoulders active throughout the set; don''t let the torso sag between reps.","dose":"6 x (7s hang / 3s rest), 3 min between sets","contraindications":"Don''t train to failure in the first sessions. Watch for any pulley (A2) pain.","equipment":["hangboard"],"disciplines":["Boulder","Route"],"energy":["Strength endurance (anaerobic lactic)"],"variants":[{"name":"Large edge (30mm+)","desc":"4 repetitions of the 7/3 cycle, comfortable hold."},{"name":"20mm edge","desc":"6 full repetitions, bodyweight."},{"name":"15mm edge, one-finger or weighted","desc":"6–8 repetitions, light added load."}]},"es":{"description":"Resistencia a la fuerza / potencia aeróbica local de los dedos","subcategory":"Resistencia-fuerza de dedos","muscles":"Flexores de los dedos, Antebrazos","cues":"Mantener los hombros activos durante toda la serie, no dejar caer el tronco entre repeticiones.","dose":"6 x (7s suspensión / 3s descanso), 3 min entre series","contraindications":"No llegar al fallo en las primeras sesiones. Vigilar cualquier dolor de polea (A2).","equipment":["tabla de dedos (hangboard)"],"disciplines":["Bloque","Vía"],"energy":["Resistencia (anaeróbica láctica)"],"variants":[{"name":"Regleta ancha (30mm+)","desc":"4 repeticiones del ciclo 7/3, presa cómoda."},{"name":"Regleta de 20mm","desc":"6 repeticiones completas, peso corporal."},{"name":"Regleta de 15mm a un dedo o lastrada","desc":"6–8 repeticiones, carga adicional ligera."}]},"meta":{"minLevel":2,"difficulty":3,"mastery":"moyen","duration":18,"period":"specifique","publics":["mixte"],"ageGroups":["jeuneAdulte","plus30","plus50"],"equipment":["poutre"],"disciplines":["bloc","voie"],"energy":["resistance"],"pose":{"pose":"hang_two_hand","equip":"bar","variants":null,"weight":[false,false,false]}}}'::jsonb),
  ('fd03', 'library', 'doigts', 'adv', '{"fr":"Max Hangs (charge maximale)","en":"Max Hangs (Maximal Load)","es":"Max Hangs (carga máxima)"}'::jsonb, '{"fr":{"description":"Force maximale, recrutement neuromusculaire","subcategory":"Force maximale doigts","muscles":"Fléchisseurs des doigts, Avant-bras","cues":"Position de crimp ou demi-crimp strictement identique à chaque série, poignet aligné, pas de à-coups.","dose":"5–6 x 6–10s à 85–95% de charge max, 3 min repos","contraindications":"Réservé aux grimpeurs avec base tendineuse solide. Échauffement long et progressif, jamais à froid.","equipment":["poutre","haltères"],"disciplines":["Bloc","Voie"],"energy":["Force maximale"],"variants":[{"name":"Charge assistée (poulie / élastique de décharge)","desc":"Réduction du poids de corps, 6s de tenue."},{"name":"Poids de corps sur réglette 20mm","desc":"8s de tenue, 5 séries, repos complet."},{"name":"Lesté +10–30% du poids de corps","desc":"Mono ou bi-doigt sur réglette 15mm, 6–8s."}]},"en":{"description":"Maximal strength, neuromuscular recruitment","subcategory":"Maximal finger strength","muscles":"Finger flexors, Forearms","cues":"Keep the crimp or half-crimp position strictly identical on every set, wrist aligned, no jerking.","dose":"5–6 x 6–10s at 85–95% of max load, 3 min rest","contraindications":"Reserved for climbers with a solid tendon base. Long, progressive warm-up; never train cold.","equipment":["hangboard","dumbbells"],"disciplines":["Boulder","Route"],"energy":["Maximal strength"],"variants":[{"name":"Assisted load (pulley / offloading band)","desc":"Reduced bodyweight, 6s hold."},{"name":"Bodyweight on a 20mm edge","desc":"8s hold, 5 sets, full rest."},{"name":"Weighted +10–30% of bodyweight","desc":"One- or two-finger on a 15mm edge, 6–8s."}]},"es":{"description":"Fuerza máxima, reclutamiento neuromuscular","subcategory":"Fuerza máxima de dedos","muscles":"Flexores de los dedos, Antebrazos","cues":"Posición de crimp o medio-crimp estrictamente idéntica en cada serie, muñeca alineada, sin tirones.","dose":"5–6 x 6–10s al 85–95% de la carga máxima, 3 min de descanso","contraindications":"Reservado a escaladores con una base tendinosa sólida. Calentamiento largo y progresivo, nunca en frío.","equipment":["tabla de dedos (hangboard)","mancuernas"],"disciplines":["Bloque","Vía"],"energy":["Fuerza máxima"],"variants":[{"name":"Carga asistida (polea / banda de descarga)","desc":"Reducción del peso corporal, 6s de tenencia."},{"name":"Peso corporal en regleta de 20mm","desc":"8s de tenencia, 5 series, descanso completo."},{"name":"Lastrado +10–30% del peso corporal","desc":"A uno o dos dedos en regleta de 15mm, 6–8s."}]},"meta":{"minLevel":3,"difficulty":5,"mastery":"eleve","duration":20,"period":"specifique","publics":["mixte"],"ageGroups":["jeuneAdulte","plus30","plus50"],"equipment":["poutre","haltères"],"disciplines":["bloc","voie"],"energy":["force-max"],"pose":{"pose":"hang_two_hand","equip":"bar","variants":null,"weight":[false,false,true]}}}'::jsonb),
  ('fd04', 'library', 'doigts', 'all', '{"fr":"Pinch block (préhension en pince)","en":"Pinch Block (Pinch Grip)","es":"Pinch block (presa en pinza)"}'::jsonb, '{"fr":{"description":"Force de pince, transfert vers les prises en pince","subcategory":"Préhension pince","muscles":"Fléchisseurs des doigts, Pouce (adducteur), Avant-bras","cues":"Pouce bien opposé aux doigts, poignet neutre, éviter de tordre le poignet pour compenser.","dose":"4–5 x 8–10s, 1–2 min repos","contraindications":"Attention à l''articulation du pouce, progressivité de la charge.","equipment":["bloc de pince","haltères"],"disciplines":["Bloc","Voie"],"energy":["Force maximale"],"variants":[{"name":"Pince large, deux mains, poids léger","desc":"Bloc large, charge légère, contrôle de la prise."},{"name":"Pince étroite, une main, poids de corps partiel","desc":"Bloc plus fin, charge suspendue partielle."},{"name":"Pince fine lestée","desc":"Bloc étroit, charge additionnelle importante, une main."}]},"en":{"description":"Pinch strength, transfer to pinch holds","subcategory":"Pinch grip","muscles":"Finger flexors, Thumb (adductor), Forearms","cues":"Thumb well opposed to the fingers, neutral wrist, avoid twisting the wrist to compensate.","dose":"4–5 x 8–10s, 1–2 min rest","contraindications":"Watch the thumb joint; increase load progressively.","equipment":["pinch block","dumbbells"],"disciplines":["Boulder","Route"],"energy":["Maximal strength"],"variants":[{"name":"Wide pinch, two hands, light weight","desc":"Wide block, light load, focus on grip control."},{"name":"Narrow pinch, one hand, partial bodyweight","desc":"Thinner block, partially suspended load."},{"name":"Weighted thin pinch","desc":"Narrow block, heavy added load, one hand."}]},"es":{"description":"Fuerza de pinza, transferencia a las presas en pinza","subcategory":"Presa en pinza","muscles":"Flexores de los dedos, Pulgar (aductor), Antebrazos","cues":"Pulgar bien opuesto a los dedos, muñeca neutra, evitar torcer la muñeca para compensar.","dose":"4–5 x 8–10s, 1–2 min de descanso","contraindications":"Prestar atención a la articulación del pulgar, progresividad de la carga.","equipment":["bloque de pinza","mancuernas"],"disciplines":["Bloque","Vía"],"energy":["Fuerza máxima"],"variants":[{"name":"Pinza ancha, dos manos, poco peso","desc":"Bloque ancho, carga ligera, control de la presa."},{"name":"Pinza estrecha, una mano, peso corporal parcial","desc":"Bloque más fino, carga suspendida parcial."},{"name":"Pinza fina lastrada","desc":"Bloque estrecho, carga adicional importante, una mano."}]},"meta":{"minLevel":0,"difficulty":3,"mastery":"faible","duration":10,"period":"generale","publics":["mixte"],"ageGroups":["moins18","jeuneAdulte","plus30","plus50"],"equipment":["bloc de pince","haltères"],"disciplines":["bloc","voie"],"energy":["force-max"],"pose":{"pose":"hang_two_hand","equip":"block","variants":null,"weight":[false,false,false]}}}'::jsonb),
  ('fd05', 'library', 'doigts', 'adv', '{"fr":"Campus board — travail des doigts","en":"Campus Board — Finger Work","es":"Campus board — trabajo de dedos"}'::jsonb, '{"fr":{"description":"Puissance et contact strength","subcategory":"Puissance-force doigts","muscles":"Fléchisseurs des doigts, Épaules, Dorsaux","cues":"Contrôler la phase de réception, ne jamais claquer les doigts sur la prise, garder les épaules engagées.","dose":"5–6 mouvements x 3–4 séries, repos complet 3 min","contraindications":"Risque élevé pour poulies et épaules. Réservé aux grimpeurs expérimentés, bien échauffés.","equipment":["campus board"],"disciplines":["Bloc"],"energy":["Puissance / explosivité"],"variants":[{"name":"Campus statique (montée contrôlée)","desc":"Déplacement lent sans lâcher de main, grandes réglettes."},{"name":"Campus doubles (1-3-5)","desc":"Mouvement dynamique bilatéral sur échelons rapprochés."},{"name":"Campus double dynamique grande amplitude (1-4-7)","desc":"Amplitude maximale, éventuellement mono-doigt à l''arrivée."}]},"en":{"description":"Power and contact strength","subcategory":"Power-strength for fingers","muscles":"Finger flexors, Shoulders, Lats","cues":"Control the catch phase, never slap the fingers onto the hold, keep the shoulders engaged.","dose":"5–6 moves x 3–4 sets, full rest 3 min","contraindications":"High risk for pulleys and shoulders. Reserved for experienced, well warmed-up climbers.","equipment":["campus board"],"disciplines":["Boulder"],"energy":["Power / explosiveness"],"variants":[{"name":"Static campussing (controlled ladder)","desc":"Slow movement without letting go, large rungs."},{"name":"Campus doubles (1-3-5)","desc":"Bilateral dynamic movement on closely spaced rungs."},{"name":"Large-amplitude double dyno (1-4-7)","desc":"Maximal reach, optionally one-finger on arrival."}]},"es":{"description":"Potencia y contact strength","subcategory":"Potencia-fuerza de dedos","muscles":"Flexores de los dedos, Hombros, Dorsales","cues":"Controlar la fase de recepción, no golpear nunca los dedos contra la presa, mantener los hombros activos.","dose":"5–6 movimientos x 3–4 series, descanso completo 3 min","contraindications":"Riesgo elevado para poleas y hombros. Reservado a escaladores experimentados y bien calentados.","equipment":["campus board"],"disciplines":["Bloque"],"energy":["Potencia / explosividad"],"variants":[{"name":"Campus estático (subida controlada)","desc":"Desplazamiento lento sin soltar la mano, cantos grandes."},{"name":"Campus dobles (1-3-5)","desc":"Movimiento dinámico bilateral en peldaños cercanos."},{"name":"Campus doble dinámico de gran amplitud (1-4-7)","desc":"Amplitud máxima, eventualmente a un dedo en la llegada."}]},"meta":{"minLevel":3,"difficulty":5,"mastery":"eleve","duration":20,"period":"specifique","publics":["mixte"],"ageGroups":["jeuneAdulte","plus30","plus50"],"equipment":["campus board"],"disciplines":["bloc"],"energy":["puissance"],"pose":{"pose":"campus_reach","equip":"wall","variants":null,"weight":[false,false,false]}}}'::jsonb),
  ('fd06', 'library', 'doigts', 'inter', '{"fr":"Système board — circuits doigts","en":"System Board — Finger Circuits","es":"System board — circuitos de dedos"}'::jsonb, '{"fr":{"description":"Force spécifique et transfert gestuel","subcategory":"Force spécifique","muscles":"Fléchisseurs des doigts, Avant-bras, Épaules","cues":"Mouvement issu des hanches et non des bras, garder le corps proche du mur.","dose":"6–10 mouvements par circuit x 3–4 circuits","contraindications":"Veiller à la symétrie gauche/droite, échauffement complet requis.","equipment":["système board"],"disciplines":["Bloc","Voie"],"energy":["Force maximale","Puissance / explosivité"],"variants":[{"name":"Circuit prises moyennes, tempo lent","desc":"Mouvement contrôlé, prises confortables."},{"name":"Circuit prises petites, tempo normal","desc":"Réglettes réduites, rythme de grimpe standard."},{"name":"Circuit micro-réglettes, bras dominant réduit","desc":"Prises minuscules, restriction volontaire d''un bras."}]},"en":{"description":"Sport-specific strength and movement transfer","subcategory":"Sport-specific strength","muscles":"Finger flexors, Forearms, Shoulders","cues":"Drive the movement from the hips rather than the arms, keep the body close to the wall.","dose":"6–10 moves per circuit x 3–4 circuits","contraindications":"Maintain left/right symmetry; full warm-up required.","equipment":["system board"],"disciplines":["Boulder","Route"],"energy":["Maximal strength","Power / explosiveness"],"variants":[{"name":"Medium-hold circuit, slow tempo","desc":"Controlled movement, comfortable holds."},{"name":"Small-hold circuit, normal tempo","desc":"Reduced edges, standard climbing pace."},{"name":"Micro-edge circuit, restricted dominant arm","desc":"Tiny holds, voluntary restriction of one arm."}]},"es":{"description":"Fuerza específica y transferencia gestual","subcategory":"Fuerza específica","muscles":"Flexores de los dedos, Antebrazos, Hombros","cues":"Movimiento generado desde las caderas y no desde los brazos, mantener el cuerpo cerca del muro.","dose":"6–10 movimientos por circuito x 3–4 circuitos","contraindications":"Cuidar la simetría izquierda/derecha, se requiere un calentamiento completo.","equipment":["system board"],"disciplines":["Bloque","Vía"],"energy":["Fuerza máxima","Potencia / explosividad"],"variants":[{"name":"Circuito de presas medianas, ritmo lento","desc":"Movimiento controlado, presas cómodas."},{"name":"Circuito de presas pequeñas, ritmo normal","desc":"Regletas reducidas, ritmo de escalada estándar."},{"name":"Circuito de microregletas, brazo dominante restringido","desc":"Presas minúsculas, restricción voluntaria de un brazo."}]},"meta":{"minLevel":2,"difficulty":4,"mastery":"moyen","duration":25,"period":"specifique","publics":["mixte"],"ageGroups":["jeuneAdulte","plus30","plus50"],"equipment":["système board"],"disciplines":["bloc","voie"],"energy":["force-max","puissance"],"pose":{"pose":"campus_reach","equip":"board","variants":null,"weight":[false,false,false]}}}'::jsonb),
  ('fd07', 'library', 'doigts', 'all', '{"fr":"Fingerboard — pyramide progressive","en":"Fingerboard — Progressive Pyramid","es":"Fingerboard — pirámide progresiva"}'::jsonb, '{"fr":{"description":"Développement complet force/résistance des doigts","subcategory":"Force-endurance doigts","muscles":"Fléchisseurs des doigts, Avant-bras","cues":"Respecter le temps de repos entre paliers pour préserver la qualité de prise.","dose":"Pyramide 10-8-6-8-10s, charge croissante puis décroissante","contraindications":"Échauffement complet, arrêter en cas de douleur articulaire.","equipment":["poutre"],"disciplines":["Bloc","Voie"],"energy":["Force maximale","Résistance (anaérobie lactique)"],"variants":[{"name":"Pyramide sur bac/jug, poids de corps","desc":"Grande prise, aucun lest, focus sur la régularité."},{"name":"Pyramide sur réglette 20mm","desc":"Prise standard, poids de corps."},{"name":"Pyramide lestée sur réglette 15mm","desc":"Charge additionnelle sur les paliers centraux."}]},"en":{"description":"Complete finger strength/endurance development","subcategory":"Finger strength-endurance","muscles":"Finger flexors, Forearms","cues":"Respect the rest time between steps to preserve grip quality.","dose":"Pyramid 10-8-6-8-10s, increasing then decreasing load","contraindications":"Full warm-up; stop if there''s joint pain.","equipment":["hangboard"],"disciplines":["Boulder","Route"],"energy":["Maximal strength","Strength endurance (anaerobic lactic)"],"variants":[{"name":"Pyramid on a jug, bodyweight","desc":"Large hold, no added weight, focus on consistency."},{"name":"Pyramid on a 20mm edge","desc":"Standard hold, bodyweight."},{"name":"Weighted pyramid on a 15mm edge","desc":"Added load on the central steps."}]},"es":{"description":"Desarrollo completo de fuerza/resistencia de los dedos","subcategory":"Fuerza-resistencia de dedos","muscles":"Flexores de los dedos, Antebrazos","cues":"Respetar el tiempo de descanso entre escalones para preservar la calidad de la presa.","dose":"Pirámide 10-8-6-8-10s, carga creciente y luego decreciente","contraindications":"Calentamiento completo, detener en caso de dolor articular.","equipment":["tabla de dedos (hangboard)"],"disciplines":["Bloque","Vía"],"energy":["Fuerza máxima","Resistencia (anaeróbica láctica)"],"variants":[{"name":"Pirámide en canto grande, peso corporal","desc":"Presa grande, sin lastre, foco en la regularidad."},{"name":"Pirámide en regleta de 20mm","desc":"Presa estándar, peso corporal."},{"name":"Pirámide lastrada en regleta de 15mm","desc":"Carga adicional en los escalones centrales."}]},"meta":{"minLevel":0,"difficulty":3,"mastery":"moyen","duration":20,"period":"generale","publics":["mixte"],"ageGroups":["moins18","jeuneAdulte","plus30","plus50"],"equipment":["poutre"],"disciplines":["bloc","voie"],"energy":["force-max","resistance"],"pose":{"pose":"hang_two_hand","equip":"bar","variants":null,"weight":[false,false,false]}}}'::jsonb),
  ('fd08', 'library', 'doigts', 'all', '{"fr":"Wrist roller (enrouleur de poignet)","en":"Wrist Roller","es":"Wrist roller (enrollador de muñeca)"}'::jsonb, '{"fr":{"description":"Renforcement global de l''avant-bras, prévention","subcategory":"Avant-bras global","muscles":"Fléchisseurs de l''avant-bras, Extenseurs de l''avant-bras","cues":"Mouvement lent et continu, éviter les à-coups qui sollicitent excessivement le coude.","dose":"3 x montée-descente complète, 1–2 min repos","contraindications":"Charge légère au départ ; prudence en cas de douleur au coude (épicondyle).","equipment":["wrist roller / bâton lesté"],"disciplines":["Polyvalent"],"energy":["Force maximale","Résistance (anaérobie lactique)"],"variants":[{"name":"Enroulement flexion seule, charge légère","desc":"Un seul sens de rotation, charge réduite."},{"name":"Alternance flexion/extension, charge moyenne","desc":"Rotation dans les deux sens."},{"name":"Charge lourde, enroulement continu","desc":"2–3 minutes sans interruption, charge élevée."}]},"en":{"description":"Overall forearm strengthening, prevention","subcategory":"Overall forearm","muscles":"Forearm flexors, Forearm extensors","cues":"Slow, continuous movement; avoid jerky motions that overload the elbow.","dose":"3 x full roll up-and-down, 1–2 min rest","contraindications":"Start with light load; caution with elbow (epicondyle) pain.","equipment":["wrist roller / weighted stick"],"disciplines":["All-round"],"energy":["Maximal strength","Strength endurance (anaerobic lactic)"],"variants":[{"name":"Flexion-only rolling, light load","desc":"Single rotation direction, reduced load."},{"name":"Alternating flexion/extension, moderate load","desc":"Rotation in both directions."},{"name":"Heavy load, continuous rolling","desc":"2–3 minutes without stopping, heavy load."}]},"es":{"description":"Fortalecimiento global del antebrazo, prevención","subcategory":"Antebrazo global","muscles":"Flexores del antebrazo, Extensores del antebrazo","cues":"Movimiento lento y continuo, evitar los tirones que sobrecargan excesivamente el codo.","dose":"3 x subida-bajada completa, 1–2 min de descanso","contraindications":"Carga ligera al principio; precaución en caso de dolor en el codo (epicóndilo).","equipment":["wrist roller / palo lastrado"],"disciplines":["Polivalente"],"energy":["Fuerza máxima","Resistencia (anaeróbica láctica)"],"variants":[{"name":"Enrollado solo en flexión, carga ligera","desc":"Un único sentido de rotación, carga reducida."},{"name":"Alternancia flexión/extensión, carga media","desc":"Rotación en ambos sentidos."},{"name":"Carga pesada, enrollado continuo","desc":"2–3 minutos sin interrupción, carga elevada."}]},"meta":{"minLevel":0,"difficulty":2,"mastery":"faible","duration":8,"period":"toute-saison","publics":["mixte"],"ageGroups":["moins18","jeuneAdulte","plus30","plus50"],"equipment":["wrist roller / bâton lesté"],"disciplines":["polyvalent"],"energy":["force-max","resistance"],"pose":{"pose":"wrist_seated","equip":"none","variants":null,"weight":[false,false,false]}}}'::jsonb),
