  ('ft04', 'library', 'tirage', 'all', '{"fr":"Lock-off training (blocage statique)","en":"Lock-off Training (Static Hold)","es":"Lock-off training (bloqueo estático)"}'::jsonb, '{"fr":{"description":"Force statique bras fléchi, tenue de bloc","subcategory":"Force statique","muscles":"Biceps, Grand dorsal, Épaules","cues":"Maintenir l''angle choisi sans dérive, respiration continue, ne pas bloquer sa respiration.","dose":"4–5 x maintien 5–15s à différents angles (90°, 120°, 150°), 2 min repos","contraindications":"Douleur au coude = arrêt immédiat.","equipment":["barre de traction"],"disciplines":["Bloc","Voie"],"energy":["Force maximale"],"variants":[{"name":"Lock-off à 90° assisté (pieds au sol)","desc":"Décharge partielle, maintien 5s."},{"name":"Lock-off poids de corps à 120°","desc":"Maintien 5–8s sans assistance."},{"name":"Lock-off lesté, angle variable, une main","desc":"Charge additionnelle, tenue courte et intense."}]},"en":{"description":"Static bent-arm strength, lock-off endurance for bouldering","subcategory":"Static strength","muscles":"Biceps, Lats, Shoulders","cues":"Hold the chosen angle without drifting, breathe continuously, don''t hold your breath.","dose":"4–5 x 5–15s hold at various angles (90°, 120°, 150°), 2 min rest","contraindications":"Elbow pain = stop immediately.","equipment":["pull-up bar"],"disciplines":["Boulder","Route"],"energy":["Maximal strength"],"variants":[{"name":"Assisted 90° lock-off (feet on ground)","desc":"Partial offload, 5s hold."},{"name":"Bodyweight lock-off at 120°","desc":"5–8s hold, unassisted."},{"name":"Weighted lock-off, variable angle, one arm","desc":"Added load, short intense hold."}]},"es":{"description":"Fuerza estática con el brazo flexionado, aguante en bloque","subcategory":"Fuerza estática","muscles":"Bíceps, Dorsal ancho, Hombros","cues":"Mantener el ángulo elegido sin ceder, respiración continua, no contener la respiración.","dose":"4–5 x tenencia de 5–15s en distintos ángulos (90°, 120°, 150°), 2 m