encia / explosividad"],"variants":[{"name":"Dominada explosiva clásica","desc":"El pecho sobrepasa claramente la barra."},{"name":"Typewriter (desplazamiento lateral arriba)","desc":"Desplazamiento lateral en la posición alta."},{"name":"Dominada con palmada","desc":"Despegue completo de las manos, recepción controlada."}]},"meta":{"minLevel":2,"difficulty":4,"mastery":"moyen","duration":12,"period":"specifique","publics":["mixte"],"ageGroups":["moins18","jeuneAdulte","plus30","plus50"],"equipment":["barre de traction"],"disciplines":["bloc"],"energy":["puissance"],"pose":{"pose":"pull_top","equip":"bar","variants":null,"weight":[false,false,true]}}}'::jsonb),
