erza máxima"],"variants":[{"name":"Frog / tuck planche","desc":"Rodillas replegadas cerca del pecho."},{"name":"Advanced tuck planche","desc":"Caderas más extendidas, rodillas todavía replegadas."},{"name":"Straddle / full planche","desc":"Piernas separadas o extendidas, cuerpo horizontal."}]},"meta":{"minLevel":4,"difficulty":5,"mastery":"eleve","duration":12,"period":"specifique","publics":["mixte"],"ageGroups":["moins18","jeuneAdulte","plus30","plus50"],"equipment":["parallettes"],"disciplines":["polyvalent"],"energy":["force-max"],"pose":{"pose":"planche","equip":"parallettes","variants":[["core_hold","parallettes"],["planche","parallettes"],["planche","parallettes"]],"weight":[false,false,false]}}}'::jsonb),
