uelo","desc":"Solo el peso del brazo, foco técnico."},{"name":"Mancuernas pequeñas (1–2kg)","desc":"Carga ligera adicional."},{"name":"Banda + mancuernas combinadas, unilateral","desc":"Mayor carga e inestabilidad."}]},"meta":{"minLevel":0,"difficulty":2,"mastery":"faible","duration":8,"period":"toute-saison","publics":["mixte"],"ageGroups":["moins18","jeuneAdulte","plus30","plus50"],"equipment":["haltères"],"disciplines":["polyvalent"],"energy":["prevention"],"pose":{"pose":"standing_reach","equip":"none","variants":null,"weight":[false,false,false]}}}'::jsonb),
