  ('eq03', 'library', 'equilibre', 'all', '{"fr":"Flagging drills (drapeaux)","en":"Flagging Drills","es":"Ejercicios de flagging (banderas)"}'::jsonb, '{"fr":{"description":"Économie de mouvement, équilibre latéral","subcategory":"Équilibre / centre de gravité","muscles":"Gainage, Jambes","cues":"Hanche qui pivote en premier, la jambe suit le mouvement du bassin.","dose":"10–15 mouvements dédiés, répétés 2–3x","contraindications":"Travailler les deux côtés de façon symétrique.","equipment":["mur de bloc"],"disciplines":["Bloc","Voie"],"energy":["Technique / gestuelle"],"variants":[{"name":"Flag intérieur simple","desc":"Jambe passée devant l''axe du corps."},{"name":"Flag arrière","desc":"Jambe passée derrière l''axe du corps."},{"name":"Flag combiné + changement de main","desc":"Association drapeau et changement de prise."}]},"en":{"description":"Movement economy, lateral balance","subcategory":"Balance / center of gravity","muscles":"Core, Legs","cues":"The hip rotates first; the leg follows the movement of the pelvis.","dose":"10–15 dedicated moves, repeated 2–3x","contraindications":"Work both sides symmetrically.","equipment":["bouldering wall"],"disciplines":["Boulder","Route"],"energy":["Technique / movement"],"variants":[{"name":"Simple inside flag","desc":"Leg passed in front of the body''s axis."},{"name":"Back flag","desc":"Leg passed behind the body''s axis."},{"name":"Combined flag + hand change","desc":"Combines flagging with a hold change."}]},"es":{"description":"Economía de movimiento, equilibrio lateral","subcategory":"Equilibrio / centro de gravedad","muscles":"Core, Piernas","cues":"La cadera gira primero, la pierna sigue el movimiento de la pelvis.","dose":"10–15 movimientos dedicados, repetidos 2–3x","contraindications":"Trabajar ambos lados de forma simétrica.","equipment":["muro de bloque"],"disciplines":["Bloque","Vía"],"energy":["Técnica / gestual"],"variants":[{"name":"Flag interior simple","desc":"Pierna cruzada por delante del eje del c