  ('eq04', 'library', 'equilibre', 'all', '{"fr":"Équilibre proprioceptif (bosu/coussin)","en":"Proprioceptive Balance (Bosu/Pad)","es":"Equilibrio propioceptivo (bosu/cojín)"}'::jsonb, '{"fr":{"description":"Stabilité générale, transfert vers les appuis précis","subcategory":"Proprioception générale","muscles":"Chevilles, Gainage, Jambes","cues":"Regard fixé sur un point stable devant soi, genoux légèrement fléchis.","dose":"3 x 30–45s / pied","contraindications":"Zone dégagée, progressivité de la difficulté.","equipment":["bosu/coussin instable"],"disciplines":["Polyvalent"],"energy":["Technique / gestuelle"],"variants":[{"name":"Deux pieds sur le bosu","desc":"Base large, stabilité facilitée."},{"name":"Un pied, statique","desc":"Appui unipodal, équilibre accru."},{"name":"Un pied + mouvement de bras ou lancer","desc":"Ajout d''une tâche de coordination."}]},"en":{"description":"General stability, transfer to precise footholds","subcategory":"General proprioception","muscles":"Ankles, Core, Legs","cues":"Fix your gaze on a stable point ahead, knees slightly bent.","dose":"3 x 30–45s / foot","contraindications":"Clear space; progressive difficulty.","equipment":["bosu/balance pad"],"disciplines":["All-round"],"energy":["Technique / movement"],"variants":[{"name":"Two feet on the bosu","desc":"Wide base, easier stability."},{"name":"One foot, static","desc":"Single-leg support, greater balance demand."},{"name":"One foot + arm movement or throw","desc":"Adds a coordination task."}]},"es":{"description":"Estabilidad general, transferencia a apoyos precisos","subcategory":"Propiocepción general","muscles":"Tobillos, Core, Piernas","cues":"Mirada fija en un punto estable delante, rodillas ligeramente flexionadas.","dose":"3 x 30–45s / pie","contraindications":"Zona despejada, dificultad progresiva.","equipment":["bosu/cojín inestable"],"disciplines":["Polivalente"],"energy":["Técnica / gestual"],"variants":[{"name":"Dos pies sobre el bosu","desc":"Base amplia, estabilidad facilitada."},{"name":"Un pie, estático","desc":"Apoyo unipodal, mayor exigencia de equilibrio."},{"name":"Un pie + movimiento de brazo o lanzamiento","desc":"Añade una tarea de coordinación."}]},"meta":{"minLevel":0,"difficulty":2,"mastery":"faible","duration":8,"period":"generale","publics":["mixte"],"ageGroups":["moins18","jeuneAdulte","plus30","plus50"],"equipment":["bosu/coussin instable"],"disciplines":["polyvalent"],"energy":["technique"],"pose":{"pose":"single_leg_balance","equip":"bosu","variants":null,"weight":[false,false,false]}}}'::jsonb),
  ('eq05', 'library', 'equilibre', 'all', '{"fr":"Traversée yeux fermés","en":"Blindfolded Traverse","es":"Travesía con ojos cerrados"}'::jsonb, '{"fr":{"description":"Renforcer la perception non-visuelle des appuis","subcategory":"Perception proprioceptive","muscles":"Corps entier","cues":"Explorer la prise avec les doigts avant de s''engager dessus.","dose":"5–8 min de traversée","contraindications":"Terrain sécurisé et connu, parade possible par un partenaire.","equipment":["mur de bloc"],"disciplines":["Bloc"],"energy":["Technique / gestuelle"],"variants":[{"name":"Prises de mains visibles, pieds yeux fermés","desc":"Difficulté partielle, mains guidées visuellement."},{"name":"Tout yeux fermés, mur très bien connu","desc":"Difficulté complète sur terrain familier."},{"name":"Yeux fermés + consignes vocales d''un partenaire","desc":"Ajout d''une composante de communication."}]},"en":{"description":"Strengthen non-visual perception of holds","subcategory":"Proprioceptive perception","muscles":"Full body","cues":"Explore the hold with your fingers before committing weight onto it.","dose":"5–8 min of traversing","contraindications":"Secure, familiar terrain; a spotting partner is possible.","equipment":["bouldering wall"],"disciplines":["Boulder"],"energy":["Technique / movement"],"variants":[{"name":"Hand holds visible, eyes closed for feet","desc":"Partial difficulty, hands guided visually."},{"name":"Fully blindfolded, very familiar wall","desc":"Full difficulty on familiar terrain."},{"name":"Blindfolded + verbal cues from a partner","desc":"Adds a communication component."}]},"es":{"description":"Reforzar la percepción no visual de los apoyos","subcategory":"Percepción propioceptiva","muscles":"Cuerpo completo","cues":"Explorar la presa con los dedos antes de comprometer el peso sobre ella.","dose":"5–8 min de travesía","contraindications":"Terreno seguro y conocido, aseguramiento posible por un compañero.","equipment":["muro de bloque"],"disciplines":["Bloque"],"energy":["Técnica / gestual"],"variants":[{"name":"Presas de mano visibles, pies con ojos cerrados","desc":"Dificultad parcial, manos guiadas visualmente."},{"name":"Todo con ojos cerrados, muro muy conocido","desc":"Dificultad completa en terreno familiar."},{"name":"Ojos cerrados + indicaciones verbales de un compañero","desc":"Añade un componente de comunicación."}]},"meta":{"minLevel":0,"difficulty":2,"mastery":"moyen","duration":10,"period":"generale","publics":["mixte"],"ageGroups":["moins18","jeuneAdulte","plus30","plus50"],"equipment":["mur de bloc"],"disciplines":["bloc"],"energy":["technique"],"pose":{"pose":"wall_traverse","equip":"wall","variants":null,"weight":[false,false,false]}}}'::jsonb),
  ('eq06', 'library', 'equilibre', 'all', '{"fr":"Drop knee / rotation de hanche","en":"Drop Knee / Hip Rotation","es":"Drop knee / rotación de cadera"}'::jsonb, '{"fr":{"description":"Économie de mouvement, ouverture active de hanche en grimpe","subcategory":"Technique de rotation","muscles":"Hanches, Adducteurs, Gainage","cues":"Rotation initiée par la hanche, genou jamais forcé au-delà du confort.","dose":"10–15 mouvements dédiés","contraindications":"Prudence en cas de sensibilité aux genoux, échauffement de hanche préalable.","equipment":["mur de bloc"],"disciplines":["Bloc","Voie"],"energy":["Technique / gestuelle"],"variants":[{"name":"Drop knee statique assisté","desc":"Mouvement lent, appui de contrôle disponible."},{"name":"Drop knee dynamique, mur vertical","desc":"Exécution fluide sur mur vertical."},{"name":"Drop knee en dévers, forte charge de corps","desc":"Contexte le plus exigeant."}]},"en":{"description":"Movement economy, active hip opening in climbing","subcategory":"Rotational technique","muscles":"Hips, Adductors, Core","cues":"Initiate the rotation from the hip; never force the knee past a comfortable range.","dose":"10–15 dedicated moves","contraindications":"Caution with sensitive knees; hip warm-up beforehand.","equipment":["bouldering wall"],"disciplines":["Boulder","Route"],"energy":["Technique / movement"],"variants":[{"name":"Assisted static drop knee","desc":"Slow movement, control support available."},{"name":"Dynamic drop knee, vertical wall","desc":"Fluid execution on a vertical wall."},{"name":"Drop knee on overhang, high body load","desc":"Most demanding context."}]},"es":{"description":"Economía de movimiento, apertura activa de cadera en escalada","subcategory":"Técnica de rotación","muscles":"Caderas, Aductores, Core","cues":"Rotación iniciada desde la cadera, la rodilla nunca se fuerza más allá de lo cómodo.","dose":"10–15 movimientos dedicados","contraindications":"Precaución en caso de sensibilidad en las rodillas, calentami