  ('vi01', 'library', 'vitesse', 'inter', '{"fr":"Répétitions chronométrées (voie de vitesse)","en":"Timed Reps (Speed Route)","es":"Repeticiones cronometradas (vía de velocidad)"}'::jsonb, '{"fr":{"description":"Performance chronométrée, automatisation gestuelle","subcategory":"Performance spécifique","muscles":"Corps entier","cues":"Automatiser la séquence avant de chercher la vitesse maximale.","dose":"4–6 x montée chronométrée, repos complet 3–5 min","contraindications":"Échauffement très complet, prioriser la technique avant la vitesse pure.","equipment":["voie de vitesse"],"disciplines":["Vitesse"],"energy":["Puissance / explosivité","Technique / gestuelle"],"variants":[{"name":"Montée contrôlée sans chrono, focus technique","desc":"Exécution lente et précise."},{"name":"Montée chronométrée sous-maximale (≈80%)","desc":"Vitesse d''exécution intermédiaire."},{"name":"Montée chronométrée maximale","desc":"Vitesse d''exécution maximale."}]},"en":{"description":"Timed performance, movement automation","subcategory":"Sport-specific performance","muscles":"Full body","cues":"Automate the sequence before chasing maximal speed.","dose":"4–6 x timed ascent, full rest 3–5 min","contraindications":"Very thorough warm-up; prioritize technique before raw speed.","equipment":["speed wall"],"disciplines":["Speed"],"energy":["Power / explosiveness","Technique / movement"],"variants":[{"name":"Controlled ascent without timing, technique focus","desc":"Slow, precise execution."},{"name":"Sub-maximal timed ascent (≈80%)","desc":"Intermediate execution speed."},{"name":"Maximal timed ascent","desc":"Maximal execution speed."}]},"es":{"description":"Rendimiento cronometrado, automatización del gesto","subcategory":"Rendimiento específico","muscles":"Cuerpo completo","cues":"Automatizar la secuencia antes de buscar la velocidad máxima.","dose":"4–6 x subida cronometrada, descanso completo de 3–5 min","contraindications":"Calentamiento muy completo, priorizar la técnica antes que la