a sin cronometrar, foco técnico","desc":"Ejecución del gesto sin presión de tiempo."},{"name":"Salida con señal sonora","desc":"Introduce una exigencia de reacción."},{"name":"Salida cronometrada competitiva","desc":"Condiciones cercanas a la competición."}]},"meta":{"minLevel":2,"difficulty":3,"mastery":"moyen","duration":15,"period":"specifique","publics":["mixte"],"ageGroups":["moins18","jeuneAdulte","plus30","plus50"],"equipment":["voie de vitesse"],"disciplines":["vitesse"],"energy":["puissance"],"pose":{"pose":"squat_bottom","equip":"none","variants":[["squat_bottom","none"],["lunge","none"],["jump_explosive","none"]],"weight":[false,false,false]}}}'::jsonb),
