  ('vi04', 'library', 'vitesse', 'all', '{"fr":"Mémorisation gestuelle / visualisation","en":"Movement Memorization / Visualization","es":"Memorización gestual / visualización"}'::jsonb, '{"fr":{"description":"Automatisation de la séquence gestuelle, réduction des hésitations","subcategory":"Automatisation technique","muscles":"Mental / système nerveux","cues":"Visualiser à vitesse réelle, pas au ralenti, pour un transfert optimal.","dose":"10–15 min de visualisation + répétition à sec","contraindications":"Aucune précaution particulière.","equipment":["aucun"],"disciplines":["Vitesse"],"energy":["Mental / respiration","Technique / gestuelle"],"variants":[{"name":"Observation vidéo + verbalisation de la séquence","desc":"Analyse et description à voix haute des mouvements."},{"name":"Répétition des gestes au sol/mur sans grimper","desc":"Reproduction physique de la séquence hors voie."},{"name":"Répétition yeux fermés en second","desc":"Visualisation intégrale sans support visuel."}]},"en":{"description":"Automating the movement sequence, reducing hesitation","subcategory":"Technical automation","muscles":"Mental / nervous system","cues":"Visualize at real speed, not in slow motion, for optimal transfer.","dose":"10–15 min of visualization + dry repetition","contraindications":"No particular precaution.","equipment":["none"],"disciplines":["Speed"],"energy":["Mental / breathing","Technique / movement"],"variants":[{"name":"Video observation + verbalizing the sequence","desc":"Analyzing and describing the moves out loud."},{"name":"Repeating moves on the ground/wall without climbing","desc":"Physically reproducing the sequence off-route."},{"name":"Eyes-closed repetition on belay","desc":"Full visualization without visual support."}]},"es":{"description":"Automatización de la secuencia de movimientos, reducción de dudas","subcategory":"Automatización técnica","muscles":"Mental / sistema nervioso","cues":"Visualizar a velocidad real, no a cámara lenta, para una transfe